//! Scene-wide Start/End crop. Classic-only; all hosts share this transaction.
use super::*;
use serde_json::json;
#[derive(Clone, Copy, Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase")]
enum Edge { Start, End }
#[derive(Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
struct Input {
    project_id: String,
    scene_id: String,
    expected_revision: u64,
    edge: Edge,
    #[schemars(range(min = 0, max = 9007199254740991_i64))]
    time: i64,
}
fn invalid(s: &str) -> CapabilityError { CapabilityError::InvalidInput(s.into()) }
fn tick(v: &Value) -> Result<i64, CapabilityError> {
    v.as_i64().filter(|n| (0..=9_007_199_254_740_991).contains(n)).ok_or_else(|| invalid("Invalid safe integer time"))
}
fn all(t: &Value) -> impl Iterator<Item=&Value> {
    std::iter::once(&t["main"]).chain(t["overlay"].as_array().into_iter().flatten()).chain(t["audio"].as_array().into_iter().flatten())
}
fn crop(track: &mut Value, low: i64, high: i64, shift: i64) -> Result<(), CapabilityError> {
    let before = track.clone();
    let elements = track["elements"].as_array_mut().ok_or_else(|| invalid("Missing track elements"))?;
    let mut kept = Vec::new();
    for e in elements.iter() {
        let start = tick(&e["startTime"])?; let duration = tick(&e["duration"])?;
        let end = start.checked_add(duration).ok_or_else(|| invalid("Clip time overflow"))?;
        let a = start.max(low); let b = end.min(high);
        if b <= a { continue; }
        let mut next = e.clone();
        if a != start || b != end {
            let left = a-start; let right = end-b;
            let rate = if matches!(e["type"].as_str(), Some("video"|"audio")) { classic_update::rate(e) } else { 1.0 };
            let source_left = (left as f64 * rate).round() as i64;
            let source_right = (duration as f64 * rate).round() as i64 - ((duration-right) as f64 * rate).round() as i64;

